body:
I was able to reproduce this issue on Godot Engine - .NET v4.7.1 for Windows x64. It appears that the source generator is unable to produce bridge code that reads from and writes to static fields like it does for instance fields. After modifying the `Script2` class like so:

```cs
using Godot;

public partial class Script2 : Node
{
	public static int Num = 42;

	public int ThisNum = 42;
}
```

The source generator produces the following bridge code:

```cs
using Godot;
using Godot.NativeInterop;

partial class Script2
{
#pragma warning disable CS0109 // Disable warning about redundant 'new' keyword
    /// <summary>
    /// Cached StringNames for the properties and fields contained in this class, for fast lookup.
    /// </summary>
    public new class PropertyName : global::Godot.Node.PropertyName {
        /// <summary>
        /// Cached name for the 'ThisNum' field.
        /// </summary>
        public new static readonly global::Godot.StringName @ThisNum = "ThisNum";
    }
    /// <inheritdoc/>
    [global::System.ComponentModel.EditorBrowsable(global::System.ComponentModel.EditorBrowsableState.Never)]
    protected override bool SetGodotClassPropertyValue(in godot_string_name name, in godot_variant value)
    {
        if (name == PropertyName.@ThisNum) {
            this.@ThisNum = global::Godot.NativeInterop.VariantUtils.ConvertTo<int>(value);
            return true;
        }
        return base.SetGodotClassPropertyValue(name, value);
    }
    /// <inheritdoc/>
    [global::System.ComponentModel.EditorBrowsable(global::System.ComponentModel.EditorBrowsableState.Never)]
    protected override bool GetGodotClassPropertyValue(in godot_string_name name, out godot_variant value)
    {
        if (name == PropertyName.@ThisNum) {
            value = global::Godot.NativeInterop.VariantUtils.CreateFrom<int>(this.@ThisNum);
            return true;
        }
        return base.GetGodotClassPropertyValue(name, out value);
    }
    /// <summary>
    /// Get the property information for all the properties declared in this class.
    /// This method is used by Godot to register the available properties in the editor.
    /// Do not call this method.
    /// </summary>
    [global::System.ComponentModel.EditorBrowsable(global::System.ComponentModel.EditorBrowsableState.Never)]
    internal new static global::System.Collections.Generic.List<global::Godot.Bridge.PropertyInfo> GetGodotPropertyList()
    {
        var properties = new global::System.Collections.Generic.List<global::Godot.Bridge.PropertyInfo>();
        properties.Add(new(type: (global::Godot.Variant.Type)2, name: PropertyName.@ThisNum, hint: (global::Godot.PropertyHint)0, hintString: "", usage: (global::Godot.PropertyUsageFlags)4096, exported: false));
        return properties;
    }
#pragma warning restore CS0109
}
```

Note the lack of references to the static `Num` field. This does not match the source generator's behavior when it comes to methods. If getter and setter methods were added to `Script2` like so:

```cs
using Godot;

public partial class Script2 : Node
{
	public static int Num = 42;

	public int ThisNum = 42;

	public static int GetNum()
	{
		return Num;
	}

	public static int SetNum(int value)
	{
		return Num = value;
	}

	public int GetThisNum()
	{
		return ThisNum;
	}

	public int SetThisNum(int value)
	{
		return ThisNum = value;
	}
}
```

The source generator produces the following bridge code:

```cs
using Godot;
using Godot.NativeInterop;

partial class Script2
{
#pragma warning disable CS0109 // Disable warning about redundant 'new' keyword
    /// <summary>
    /// Cached StringNames for the methods contained in this class, for fast lookup.
    /// </summary>
    public new class MethodName : global::Godot.Node.MethodName {
        /// <summary>
        /// Cached name for the 'GetNum' method.
        /// </summary>
        public new static readonly global::Godot.StringName @GetNum = "GetNum";
        /// <summary>
        /// Cached name for the 'SetNum' method.
        /// </summary>
        public new static readonly global::Godot.StringName @SetNum = "SetNum";
        /// <summary>
        /// Cached name for the 'GetThisNum' method.
        /// </summary>
        public new static readonly global::Godot.StringName @GetThisNum = "GetThisNum";
        /// <summary>
        /// Cached name for the 'SetThisNum' method.
        /// </summary>
        public new static readonly global::Godot.StringName @SetThisNum = "SetThisNum";
    }
    /// <summary>
    /// Get the method information for all the methods declared in this class.
    /// This method is used by Godot to register the available methods in the editor.
    /// Do not call this method.
    /// </summary>
    [global::System.ComponentModel.EditorBrowsable(global::System.ComponentModel.EditorBrowsableState.Never)]
    internal new static global::System.Collections.Generic.List<global::Godot.Bridge.MethodInfo> GetGodotMethodList()
    {
        var methods = new global::System.Collections.Generic.List<global::Godot.Bridge.MethodInfo>(4);
        methods.Add(new(name: MethodName.@GetNum, returnVal: new(type: (global::Godot.Variant.Type)2, name: "", hint: (global::Godot.PropertyHint)0, hintString: "", usage: (global::Godot.PropertyUsageFlags)6, exported: false), flags: (global::Godot.MethodFlags)33, arguments: null, defaultArguments: null));
        methods.Add(new(name: MethodName.@SetNum, returnVal: new(type: (global::Godot.Variant.Type)2, name: "", hint: (global::Godot.PropertyHint)0, hintString: "", usage: (global::Godot.PropertyUsageFlags)6, exported: false), flags: (global::Godot.MethodFlags)33, arguments: new() { new(type: (global::Godot.Variant.Type)2, name: "value", hint: (global::Godot.PropertyHint)0, hintString: "", usage: (global::Godot.PropertyUsageFlags)6, exported: false),  }, defaultArguments: null));
        methods.Add(new(name: MethodName.@GetThisNum, returnVal: new(type: (global::Godot.Variant.Type)2, name: "", hint: (global::Godot.PropertyHint)0, hintString: "", usage: (global::Godot.PropertyUsageFlags)6, exported: false), flags: (global::Godot.MethodFlags)1, arguments: null, defaultArguments: null));
        methods.Add(new(name: MethodName.@SetThisNum, returnVal: new(type: (global::Godot.Variant.Type)2, name: "", hint: (global::Godot.PropertyHint)0, hintString: "", usage: (global::Godot.PropertyUsageFlags)6, exported: false), flags: (global::Godot.MethodFlags)1, arguments: new() { new(type: (global::Godot.Variant.Type)2, name: "value", hint: (global::Godot.PropertyHint)0, hintString: "", usage: (global::Godot.PropertyUsageFlags)6, exported: false),  }, defaultArguments: null));
        return methods;
    }
#pragma warning restore CS0109
    /// <inheritdoc/>
    [global::System.ComponentModel.EditorBrowsable(global::System.ComponentModel.EditorBrowsableState.Never)]
    protected override bool InvokeGodotClassMethod(in godot_string_name method, NativeVariantPtrArgs args, out godot_variant ret)
    {
        if (method == MethodName.@GetNum && args.Count == 0) {
            var callRet = @GetNum();
            ret = global::Godot.NativeInterop.VariantUtils.CreateFrom<int>(callRet);
            return true;
        }
        if (method == MethodName.@SetNum && args.Count == 1) {
            var callRet = @SetNum(global::Godot.NativeInterop.VariantUtils.ConvertTo<int>(args[0]));
            ret = global::Godot.NativeInterop.VariantUtils.CreateFrom<int>(callRet);
            return true;
        }
        if (method == MethodName.@GetThisNum && args.Count == 0) {
            var callRet = @GetThisNum();
            ret = global::Godot.NativeInterop.VariantUtils.CreateFrom<int>(callRet);
            return true;
        }
        if (method == MethodName.@SetThisNum && args.Count == 1) {
            var callRet = @SetThisNum(global::Godot.NativeInterop.VariantUtils.ConvertTo<int>(args[0]));
            ret = global::Godot.NativeInterop.VariantUtils.CreateFrom<int>(callRet);
            return true;
        }
        return base.InvokeGodotClassMethod(method, args, out ret);
    }
#pragma warning disable CS0109 // Disable warning about redundant 'new' keyword
    [global::System.ComponentModel.EditorBrowsable(global::System.ComponentModel.EditorBrowsableState.Never)]
    internal new static bool InvokeGodotClassStaticMethod(in godot_string_name method, NativeVariantPtrArgs args, out godot_variant ret)
    {
        if (method == MethodName.@GetNum && args.Count == 0) {
            var callRet = @GetNum();
            ret = global::Godot.NativeInterop.VariantUtils.CreateFrom<int>(callRet);
            return true;
        }
        if (method == MethodName.@SetNum && args.Count == 1) {
            var callRet = @SetNum(global::Godot.NativeInterop.VariantUtils.ConvertTo<int>(args[0]));
            ret = global::Godot.NativeInterop.VariantUtils.CreateFrom<int>(callRet);
            return true;
        }
        ret = default;
        return false;
    }
#pragma warning restore CS0109
    /// <inheritdoc/>
    [global::System.ComponentModel.EditorBrowsable(global::System.ComponentModel.EditorBrowsableState.Never)]
    protected override bool HasGodotClassMethod(in godot_string_name method)
    {
        if (method == MethodName.@GetNum) {
           return true;
        }
        if (method == MethodName.@SetNum) {
           return true;
        }
        if (method == MethodName.@GetThisNum) {
           return true;
        }
        if (method == MethodName.@SetThisNum) {
           return true;
        }
        return base.HasGodotClassMethod(method);
    }
}
```

The source generator is able to produce bridge code for static methods, but it is not able to produce bridge code for static fields. This does not change when `Num` is implemented as a static property with public getters and setters instead. As it stands now, the only way to access static C# fields and properties from GDScript is through static methods.
